DAY = "2026-10-{:02d}T10:00:00+00:00"


class GitRepo:
    """A git repository in a temporary folder, whose commits are made with given authors, dates and trailers."""

    def __init__(self, folder):
        self.top = Path(folder)
        self.top.mkdir(parents=True, exist_ok=True)
        self.git("init", "-q", "-b", "main")
        self.day = 0

    def git(self, *args, env=None):
        full = dict(os.environ, **(env or {}))
        return subprocess.run(["git", *args], cwd=self.top, env=full, check=True, capture_output=True,
                              text=True, encoding="utf-8").stdout

    def write(self, path, text):
        target = self.top / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding="utf-8", newline="\n")

    def commit(self, files, author="Alice <alice@example.com>", message="change", co_authors=(),
               committer=None):
        for path, text in files.items():
            self.write(path, text)
        self.git("add", "-A")
        self.day += 1
        name, _, mail = author.partition(" <")
        committer_name, _, committer_mail = (committer or author).partition(" <")
        body = message + ("\n\n" + "\n".join(f"Co-Authored-By: {c}" for c in co_authors) if co_authors else "")
        self.git("commit", "-q", "-m", body, env={
            "GIT_AUTHOR_NAME": name, "GIT_AUTHOR_EMAIL": mail.rstrip(">"), "GIT_AUTHOR_DATE": DAY.format(self.day),
            "GIT_COMMITTER_NAME": committer_name, "GIT_COMMITTER_EMAIL": committer_mail.rstrip(">"),
            "GIT_COMMITTER_DATE": DAY.format(self.day)})

    def merge(self, branch, message):
        """A merge commit of branch into the branch checked out, by Dan, a day after the last commit."""
        self.day += 1
        self.git("merge", "-q", "--no-ff", "-m", message, branch, env={
            "GIT_AUTHOR_NAME": "Dan", "GIT_AUTHOR_EMAIL": "dan@example.com", "GIT_AUTHOR_DATE": DAY.format(self.day),
            "GIT_COMMITTER_NAME": "Dan", "GIT_COMMITTER_EMAIL": "dan@example.com",
            "GIT_COMMITTER_DATE": DAY.format(self.day)})


def setUpModule():
    folder = tempfile.mkdtemp(prefix="agnos-history-config-")
    empty = Path(folder) / "gitconfig"
    empty.write_text("[init]\n\tdefaultBranch = main\n", encoding="utf-8")
    patcher = mock.patch.dict(os.environ, {"GIT_CONFIG_GLOBAL": str(empty), "GIT_CONFIG_NOSYSTEM": "1"})
    patcher.start()
    unittest.addModuleCleanup(patcher.stop)
    unittest.addModuleCleanup(shutil.rmtree, folder, ignore_errors=True)


class RepoTestCase(unittest.TestCase):
    def setUp(self):
        self.folder = Path(tempfile.mkdtemp(prefix="agnos-history-"))
        self.addCleanup(shutil.rmtree, self.folder, ignore_errors=True)
        self.repo = GitRepo(self.folder / "repo")

    def people(self, patterns=None):
        repo = history.check_repository(self.repo.top)
        commits = history.read_commits(repo)
        return history.identify(repo, commits, patterns or history.load_agent_patterns())


def numbered(first, last, tag="line"):
    return "".join(f"{tag} {n}\n" for n in range(first, last + 1))


FEATURE = "process/FTR-A.md"
ALICE = "Alice <alice@example.com>"
BOB = "Bob <bob@example.com>"
CAROL = "Carol <carol@example.com>"




INDEX_TEXT = """# AGNOS process index - GENERATED by the agnos-index skill, never edit by hand.
@process/1.requirements/FTR-ABC-001.md
FTR-ABC-001|1-20||Feature
RQ-ABC-001|5-10||First
RQ-ABC-002|12-20||Second
"""
CODE = "src/app.py"
CODE_TEXT = "# RQ-ABC-001\ndef f():\n    return 1\n\n\n# RQ-ABC-002\ndef g():\n    return 2\n"
GENERATED_AT = "2026-10-24T12:00Z"
HAS_TREE_SITTER = importlib.util.find_spec("tree_sitter") is not None


class GeneratorTest(RepoTestCase):
    """TASK-HST-003: RQ-HST-001, RQ-HST-006, RQ-HST-012, RQ-HST-015."""

    def setUp(self):
        super().setUp()
        lines = numbered(1, 20)
        self.feature = "process/1.requirements/FTR-ABC-001.md"
        self.repo.commit({f"process/{agnos_layout.INDEX}": INDEX_TEXT, self.feature: lines, CODE: CODE_TEXT}, author=CAROL)
        self.repo.commit({self.feature: lines.replace("line 7\n", "line seven\n")}, author=ALICE, co_authors=[CLAUDE])
        self.out = self.folder / "out" / "TRACE.html"

    def run_generator(self, *extra, process=None):
        process = process or self.repo.top / "process"
        return run_main(["--process", str(process), "--sources", str(self.repo.top / "src"), "--out", str(self.out),
                         "--generated-at", GENERATED_AT, *extra])

    def data(self):
        return json.loads(self.out.with_suffix(".json").read_text(encoding="utf-8"))

    def test_RQ_HST_001_given_a_history_limit_without_history_then_the_exit_code_is_1_and_names_the_option(self):
        for extra in (["--history-depth", "5"], ["--history-since", "6.months"]):
            code, _, err = self.run_generator(*extra)
            self.assertEqual(1, code, extra)
            self.assertIn("--history", err)

    def test_RQ_HST_001_given_a_depth_that_is_not_a_positive_integer_then_the_exit_code_is_1(self):
        for depth in ("0", "-3", "ten"):
            code, _, err = self.run_generator("--history", "--history-depth", depth)
            self.assertEqual(1, code, depth)
            self.assertIn("--history-depth", err)

    def test_RQ_HST_006_given_a_run_with_history_then_the_data_holds_the_history_block_and_the_summary_its_counts(self):
        code, out, err = self.run_generator("--history")
        self.assertEqual(0, code, err)
        block = self.data()["history"]
        self.assertEqual({"limits", "people", "commits", "interventions", "graph"}, set(block))   # RQ-HST-024
        self.assertEqual({"since": None, "depth": None, "commits": 2, "first": "2026-10-01T10:00:00Z", "last": "2026-10-02T10:00:00Z",
                          "shallow": False}, block["limits"])
        self.assertEqual(["Alice", "Carol", "Claude Opus 5.5"], sorted(p["name"] for p in block["people"]))
        first, second = block["commits"]
        self.assertEqual("Carol", block["people"][first["author"]]["name"])
        self.assertEqual(TOGETHER, second["kind"])
        elements = block["interventions"]["elements"]
        self.assertEqual([[0, 6], [1, 2]], elements["RQ-ABC-001"])
        self.assertEqual([[0, 9]], elements["RQ-ABC-002"])
        files = block["interventions"]["files"]
        self.assertEqual({p["path"] for p in self.data()["files"]}, set(files))
        self.assertEqual([[0, 8]], next(iter(files.values())))
        self.assertNotIn("functions", block["interventions"])
        self.assertIn("history: 2 commits, 2 humans, 1 agent;", out)   # TASK-TRC-055: singular for one

    def test_RQ_HST_001_given_limits_then_they_are_applied_and_written(self):
        code, _, err = self.run_generator("--history", "--history-depth", "1", "--history-since", "2026-10-01")
        self.assertEqual(0, code, err)
        block = self.data()["history"]
        self.assertEqual(1, block["limits"]["depth"])
        self.assertEqual("2026-10-01", block["limits"]["since"])
        self.assertEqual(1, block["limits"]["commits"])
        self.assertEqual([[0, 2]], block["interventions"]["elements"]["RQ-ABC-001"])

    def test_RQ_HST_006_given_two_runs_then_the_data_files_are_equal(self):
        self.run_generator("--history")
        first = self.out.with_suffix(".json").read_bytes()
        self.run_generator("--history")
        self.assertEqual(first, self.out.with_suffix(".json").read_bytes())

    def test_RQ_HST_015_given_no_history_option_then_no_history_is_read_or_written(self):
        with mock.patch.object(gr, "load_history_module", side_effect=AssertionError("history loaded")):  # TASK-TRC-118
            code, out, err = self.run_generator()
        self.assertEqual(0, code, err)
        self.assertNotIn("history", self.data())
        self.assertNotIn("history:", out)

    def test_RQ_HST_012_given_a_process_folder_outside_git_then_a_warning_and_no_history(self):
        outside = Path(tempfile.mkdtemp(prefix="agnos-history-outside-", dir=os.environ.get("TEMP")))
        self.addCleanup(shutil.rmtree, outside, ignore_errors=True)
        shutil.copytree(self.repo.top / "process", outside / "process")
        with mock.patch.dict(os.environ, {"GIT_CEILING_DIRECTORIES": str(outside)}):
            code, _, err = self.run_generator("--history", process=outside / "process")
        self.assertEqual(0, code, err)
        self.assertIn("warning", err)
        self.assertIn("not inside a git working tree", err)
        self.assertNotIn("history", self.data())

    @unittest.skipUnless(HAS_TREE_SITTER, "tree-sitter is not installed")
    def test_RQ_HST_003_given_a_call_graph_then_the_functions_have_their_interventions(self):
        code_lines = CODE_TEXT.replace("return 2", "return 3")
        self.repo.commit({CODE: code_lines}, author=BOB)
        code, _, err = self.run_generator("--history", "--call-graph")
        self.assertEqual(0, code, err)
        data = self.data()
        names = [f[3] for f in data["callGraph"]["functions"]]
        functions = data["history"]["interventions"]["functions"]
        people = data["history"]["people"]
        commits = data["history"]["commits"]
        authors = {name: sorted(people[commits[c]["author"]]["name"] for c, _ in functions[str(n)])
                   for n, name in enumerate(names)}
        self.assertEqual({"f": ["Carol"], "g": ["Bob", "Carol"]}, authors)




